#[test]
fn parity_order_restated_full() {
    let mut row = synthetic_row(b'R', 14);
    row.push(0);
    row.push(0);
    let tag_display_quantity_bytes: [u8; 4] = synthetic_bytes(82, 4).try_into().unwrap();
    let tag_display_quantity_v = u32::from_be_bytes(tag_display_quantity_bytes);
    let tag_display_price_bytes: [u8; 8] = synthetic_bytes(105, 8).try_into().unwrap();
    let tag_display_price_v = u64::from_be_bytes(tag_display_price_bytes);
    let tag_secondary_ord_ref_num_bytes: [u8; 8] = synthetic_bytes(128, 8).try_into().unwrap();
    let tag_secondary_ord_ref_num_v = u64::from_be_bytes(tag_secondary_ord_ref_num_bytes);
    let tag_user_ref_idx_bytes: [u8; 1] = synthetic_bytes(151, 1).try_into().unwrap();
    let tag_user_ref_idx_v = u8::from_be_bytes(tag_user_ref_idx_bytes);
    append_tag(&mut row, 22, &tag_display_quantity_bytes);
    append_tag(&mut row, 23, &tag_display_price_bytes);
    append_tag(&mut row, 1, &tag_secondary_ord_ref_num_bytes);
    append_tag(&mut row, 28, &tag_user_ref_idx_bytes);
    let tail_len = (row.len() - 14 - 2) as u16;
    row[14..14 + 2].copy_from_slice(&tail_len.to_be_bytes());
    let owned = match support::owned_ouch_v5::decode_from_exchange(&row).expect("baseline decodes") {
        support::owned_ouch_v5::OwnedMessage::OrderRestated(m) => m,
        other => panic!("expected OrderRestated, got {other:?}"),
    };
    let v = OrderRestatedView::parse(&row).expect("view parses");
    assert_eq!(v.timestamp(), owned.timestamp, "timestamp");
    assert_eq!(v.user_ref_num(), owned.user_ref_num, "user_ref_num");
    assert_eq!(v.reason(), owned.reason, "reason");
    let got: Vec<(u8, Vec<u8>)> = v.appendage().map(|(t, val)| (t, val.to_vec())).collect();
    assert_eq!(got, owned.appendage, "appendage tail");
    let mut tags = v.tags();
    assert_eq!(tags.next(), Some(AppendageTag::DisplayQuantity(tag_display_quantity_v)), "display_quantity typed");
    assert_eq!(tags.next(), Some(AppendageTag::DisplayPrice(tag_display_price_v)), "display_price typed");
    assert_eq!(tags.next(), Some(AppendageTag::SecondaryOrdRefNum(tag_secondary_ord_ref_num_v)), "secondary_ord_ref_num typed");
    assert_eq!(tags.next(), Some(AppendageTag::UserRefIdx(tag_user_ref_idx_v)), "user_ref_idx typed");
    assert_eq!(tags.next(), None, "no extra tags");
}

