#[test]
fn parity_enter_order_build() {
    let mut buf = [0u8; EnterOrderBuilder::FIXED_LEN];
    let mut b = EnterOrderBuilder::new(&mut buf);
    let user_ref_num_v: u32 = u32::from_be_bytes(synthetic_bytes(79, 4).try_into().unwrap());
    b.set_user_ref_num(user_ref_num_v);
    let side_v: u8 = synthetic_bytes(102, 1)[0];
    b.set_side(side_v);
    let quantity_v: u32 = u32::from_be_bytes(synthetic_bytes(125, 4).try_into().unwrap());
    b.set_quantity(quantity_v);
    let symbol_v: [u8; 8] = synthetic_alpha(148, 8).try_into().unwrap();
    b.set_symbol(&symbol_v);
    let price_v: u64 = u64::from_be_bytes(synthetic_bytes(171, 8).try_into().unwrap());
    b.set_price(price_v);
    let time_in_force_v: u8 = synthetic_bytes(194, 1)[0];
    b.set_time_in_force(time_in_force_v);
    let display_v: u8 = synthetic_bytes(217, 1)[0];
    b.set_display(display_v);
    let capacity_v: u8 = synthetic_bytes(240, 1)[0];
    b.set_capacity(capacity_v);
    let inter_market_sweep_eligibility_v: u8 = synthetic_bytes(7, 1)[0];
    b.set_inter_market_sweep_eligibility(inter_market_sweep_eligibility_v);
    let cross_type_v: u8 = synthetic_bytes(30, 1)[0];
    b.set_cross_type(cross_type_v);
    let cl_ord_id_v: [u8; 14] = synthetic_alpha(53, 14).try_into().unwrap();
    b.set_cl_ord_id(&cl_ord_id_v);
    let n = b.finish();
    assert_eq!(n, EnterOrderBuilder::FIXED_LEN, "finish length, no tags");
    let owned = match support::owned_ouch_v5::decode_to_exchange(&buf[..n]).expect("baseline decodes") {
        support::owned_ouch_v5::OwnedMessage::EnterOrder(m) => m,
        other => panic!("expected EnterOrder, got {other:?}"),
    };
    assert_eq!(owned.user_ref_num, user_ref_num_v, "user_ref_num");
    assert_eq!(owned.side, side_v, "side");
    assert_eq!(owned.quantity, quantity_v, "quantity");
    assert_eq!(&owned.symbol[..], &symbol_v[..], "symbol");
    assert_eq!(owned.price, price_v, "price");
    assert_eq!(owned.time_in_force, time_in_force_v, "time_in_force");
    assert_eq!(owned.display, display_v, "display");
    assert_eq!(owned.capacity, capacity_v, "capacity");
    assert_eq!(owned.inter_market_sweep_eligibility, inter_market_sweep_eligibility_v, "inter_market_sweep_eligibility");
    assert_eq!(owned.cross_type, cross_type_v, "cross_type");
    assert_eq!(&owned.cl_ord_id[..], &cl_ord_id_v[..], "cl_ord_id");
    assert_eq!(owned.appendage.len(), 0, "no tags appended");
}

